  // Watches real mic volume while a recording is live, for the "talking" trainer
  // emoji — taps the exact same getUserMedia stream every recorder already opens
  // (no extra permission prompt, no second mic grab), reads it through a Web Audio
  // AnalyserNode, and exposes a smoothed 0–1 loudness level via requestAnimationFrame.
  // Every voice button in the app shares this one hook so the emoji reacts the same
  // way everywhere. If Web Audio is unsupported/blocked, level just stays 0 and the
  // emoji sits still — recording and transcription are completely unaffected either way.
  function useTalkingLevel() {
    const [level, setLevel] = useState(0);
    const audioCtxRef = useRef(null);
    const analyserRef = useRef(null);
    const dataRef = useRef(null);
    const rafRef = useRef(null);

    function attach(stream) {
      try {
        const AudioCtx = window.AudioContext || window.webkitAudioContext;
        if (!AudioCtx) return;
        const ctx = new AudioCtx();
        ctx.resume().catch(() => {}); // Safari can start a context "suspended" if it wasn't created inside the click itself — harmless no-op elsewhere
        const source = ctx.createMediaStreamSource(stream);
        const analyser = ctx.createAnalyser();
        analyser.fftSize = 256;
        analyser.smoothingTimeConstant = 0.55;
        source.connect(analyser);
        audioCtxRef.current = ctx;
        analyserRef.current = analyser;
        dataRef.current = new Uint8Array(analyser.frequencyBinCount);
        const tick = () => {
          if (!analyserRef.current) return;
          analyserRef.current.getByteFrequencyData(dataRef.current);
          let sum = 0;
          for (let i = 0; i < dataRef.current.length; i++) sum += dataRef.current[i];
          const avg = sum / dataRef.current.length / 255; // 0..1
          setLevel(Math.min(1, avg * 2.6)); // normal speaking volume rarely maxes the raw average — scale up so quiet speech still visibly moves it
          rafRef.current = requestAnimationFrame(tick);
        };
        tick();
      } catch (e) { /* Web Audio unsupported/blocked — emoji just stays still */ }
    }

    function detach() {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
      analyserRef.current = null;
      if (audioCtxRef.current) { audioCtxRef.current.close().catch(() => {}); audioCtxRef.current = null; }
      setLevel(0);
    }

    useEffect(() => () => detach(), []);
    return { level, attach, detach };
  }

