  function muscleRegionFill(regionKey, primaryKey, secondarySet) {
    // A visible (not near-transparent) neutral tone by default — this needs to
    // read as "a body" even where nothing is highlighted, not just show a few
    // colored blobs floating with nothing around them.
    if (!regionKey) return C.cardBorderStrong;
    // primaryKey is normally one exercise's single primary muscle (a string),
    // but the weekly muscle-balance view below needs to light up several
    // muscles as "trained" at once — accepting a Set here too (instead of a
    // second near-duplicate fill function) keeps both views drawing from the
    // exact same tier logic.
    const isPrimary = primaryKey instanceof Set ? primaryKey.has(regionKey) : primaryKey === regionKey;
    if (isPrimary) return C.brand;
    if (secondarySet.has(regionKey)) return withAlpha(C.brand, 0.45);
    return C.cardBorderStrong;
  }

