  // highest-stakes deletes first (a whole client, and clearing a client's
  // workout history) — see handleDeleteClient/handleClearWorkouts below.
  // Sept 16 2026, Jimmy: account-deletion work (Apple guideline 5.1.1(v) —
  // an app that supports account creation must let someone delete their own
  // account from inside the app). This is the highest-stakes "Delete" this
  // dialog is ever used for — a mistap on a client card is annoying and
  // recoverable by re-adding them; deleting your own login isn't — so
  // ConfirmDialog picked up an optional typed-confirmation gate rather than
  // spinning up a second, near-identical modal just for this one case.
  // Every existing call site (roster removal, set deletion, etc.) passes no
  // `requireTyped` and is completely unchanged.
  function ConfirmDialog({ title, message, confirmLabel = "Delete", onConfirm, onCancel, requireTyped = null, busy = false, extra = null }) {
    const [typed, setTyped] = useState("");
    const locked = !!requireTyped && typed.trim().toUpperCase() !== requireTyped.toUpperCase();
    return e("div", { style: styles.overlay, onClick: busy ? undefined : onCancel },
      e("div", { style: { ...styles.sheet, maxWidth: 420 }, onClick: (ev) => ev.stopPropagation() },
        e("span", { style: styles.sheetTitle }, title),
        e("p", { style: { ...styles.profileGoalText, marginTop: 10, marginBottom: requireTyped ? 14 : 22 } }, message),
        requireTyped && e("input", {
          type: "text", value: typed, onChange: (ev) => setTyped(ev.target.value),
          placeholder: `Type ${requireTyped} to confirm`, autoCapitalize: "characters",
          style: { ...styles.input, marginBottom: 18 }
        }),
        extra,
        e("div", { style: { display: "flex", gap: 10 } },
          e("button", { style: styles.confirmCancelBtn, onClick: onCancel, disabled: busy }, "Cancel"),
          e("button", {
            style: { ...styles.confirmDangerBtn, ...((locked || busy) ? styles.btnDisabled : {}) },
            disabled: locked || busy,
            onClick: onConfirm
          }, busy ? "Working…" : confirmLabel)
        )
      )
    );
  }

  // Sept 18 2026, Jimmy: "admin nav got flattened into one unlabeled Menu"
  // review finding — this used to only ever take a flat `items` array,
  // which is exactly what made CoachView's own admin menu read as one long
  // undifferentiated list (Dashboard, Rota, Trainers, Clients, Gyms, both
  // billing screens, three request inboxes, Diet templates, Exercise
  // Library, AI Chat, all mixed together). Added an optional `groups` prop
  // — an array of {label, items} — that renders a small section header
  // above each cluster instead. Backward compatible: every existing caller
  // (the two client-detail SideMenu uses, which are short single-purpose
  // lists that never needed grouping) still just passes `items` and is
  // completely unaffected.
  function SideMenu({ onClose, title, items, groups }) {
    function renderItem(it) {
      return e("button", {
        key: it.label,
        style: { ...styles.sideMenuItem, ...(it.active ? styles.sideMenuItemActive : {}) },
        onClick: it.onClick
      }, it.label);
    }
    return e("div", { style: styles.sideMenuOverlay, onClick: onClose },
      e("div", { style: styles.sideMenuPanel, onClick: (ev) => ev.stopPropagation() },
        e("div", { style: styles.sheetHeader },
          e("span", { style: styles.sheetTitle }, title || "Menu"),
          e("button", { style: styles.closeBtn, onClick: onClose }, e(Icon, { name: "x", size: 18 }))
        ),
        Array.isArray(groups)
          ? e("div", { style: styles.sideMenuList }, groups.map((g) => e(React.Fragment, { key: g.label },
              e("div", { style: styles.sideMenuGroupLabel }, g.label),
              g.items.map(renderItem)
            )))
          : e("div", { style: styles.sideMenuList }, items.map(renderItem))
      )
    );
  }

  // Tap-to-start rest timer. Counts down locally in the browser — no server
  // round trip needed, so it works instantly between sets.
  function RestTimerChip({ seconds }) {
    const [remaining, setRemaining] = useState(null);
    useEffect(() => {
      if (remaining === null || remaining <= 0) return;
      const id = setTimeout(() => setRemaining((r) => (r === null ? null : r - 1)), 1000);
      return () => clearTimeout(id);
    }, [remaining]);
    if (!seconds) return null;
    const running = remaining !== null && remaining > 0;
    const done = remaining === 0;
    function handleTap(ev) {
      ev.stopPropagation();
      setRemaining(seconds);
    }
    const mm = remaining != null ? Math.floor(remaining / 60) : 0;
    const ss = remaining != null ? remaining % 60 : 0;
    const label = running ? `${mm}:${String(ss).padStart(2, "0")}` : done ? "Rest done" : `Rest ${fmtRest(seconds)}`;
    return e("button", {
      style: {
        ...styles.setChip,
        cursor: "pointer",
        ...(running ? { color: C.brand, borderColor: withAlpha(C.brand, 0.4), background: C.brandSoft } : {}),
        ...(done ? { color: C.good, borderColor: withAlpha(C.good, 0.4), background: C.goodSoft } : {})
      },
      onClick: handleTap
    }, e(Icon, { name: "flame", size: 10, strokeWidth: 2.5 }), label);
  }

  // Reusable "how to pay" box — same Whish name/number everywhere a client
  // is told a payment is pending, so it's not just "ask your gym" with no
  // way to actually act on it. amount/note are optional; pass them to add
  // the "Send $X..." line under the box, same wording each screen used to
  // write out by hand.
  function WhishPayBox({ amount = null, note = "" }) {
    return e(React.Fragment, null,
      e("div", { style: { background: withAlpha(C.brand, 0.08), borderRadius: 10, padding: "10px 12px", width: "100%" } },
        e("p", { style: { margin: 0, fontSize: 12, color: C.ink3, textTransform: "uppercase", letterSpacing: "0.04em", fontWeight: 700 } }, "Pay via Whish Money"),
        e("p", { style: { margin: "4px 0 0", fontSize: 14, fontWeight: 600, color: C.ink } }, WHISH_NAME),
        e("p", { style: { margin: "2px 0 0", fontSize: 14, fontFamily: "'JetBrains Mono', monospace", color: C.ink } }, WHISH_NUMBER)
      ),
      // Sept 13 2026, Jimmy: "exact same the photo" — jimfit-flow_15.html
      // shows this line bold and gold/amber, not the small gray caption it
      // used to be; same gold as the SlideToUnlock lock icon.
      amount != null && e("p", { style: { margin: "8px 0 0", fontSize: 16, fontWeight: 700, color: "#F5C542", textAlign: "center" } }, `Send $${amount}${note ? `, ${note}` : ""}`)
    );
  }

export { Icon, MUSCLE_COLORS, BirthdayBadge, Dot, Segmented, Select, ClientPicker, useTalkingLevel, TalkingTrainerEmoji, VoiceLoadingDots, StatTile, muscleRegionFill, MuscleDiagramView, MuscleDiagram, DashboardStatGrid, ConfirmDialog, SideMenu, RestTimerChip, WhishPayBox };
